CustomField.formula:
DATETIMEVALUE(
  /* build an ISO datetime string */
  TEXT(  Daily_Dispatch__r.Dispatch_Date__c  )
  & " "
  /* if you only have “HH:MM”, append “:00” for the seconds */
  & IF(
      CONTAINS(  Collection_Schedule__r.Time__c , ":" ),
      /* has “:”, assume “HH:MM” or “HH:MM:SS” */
      IF(
        LEN( Collection_Schedule__r.Time__c ) = 5,
        /* “HH:MM” → add “:00” */
        Collection_Schedule__r.Time__c & ":00",
        /* already “HH:MM:SS” */
        Collection_Schedule__r.Time__c
      ),
      /* no “:”, treat whole text as hour */
      LPAD( Collection_Schedule__r.Time__c, 2 , "0" ) & ":00:00"
    )
)
